package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
)

type MyError struct{ Code int }

func (e *MyError) Error() string { return fmt.Sprintf("code=%d", e.Code) }

// 反例：返回类型是 error，内部用具体指针，触发 typed nil。
func badDo(ok bool) error {
	var e *MyError
	if !ok {
		e = &MyError{Code: 500}
	}
	return e // 即使 e==nil，接口的 itab 已经是 *MyError，外层 != nil 成立
}

// 正例：要么显式判空回 nil，要么直接返回 error 字面量。
func goodDo(ok bool) error {
	if ok {
		return nil
	}
	return &MyError{Code: 500}
}

func main() {
	// 1) typed nil：接口里有动态类型 *bytes.Buffer，所以 r == nil 为 false
	var buf *bytes.Buffer
	var r io.Reader = buf
	fmt.Println("r == nil:", r == nil)        // false
	fmt.Println("buf == nil:", buf == nil)    // true

	// 2) badDo vs goodDo
	fmt.Println("badDo:", badDo(true) == nil)   // false（陷阱）
	fmt.Println("goodDo:", goodDo(true) == nil) // true

	// 3) comma-ok 断言 + errors.As
	var err error = &MyError{Code: 404}
	if me, ok := err.(*MyError); ok {
		fmt.Println("asserted code:", me.Code)
	}
	var target *MyError
	if errors.As(err, &target) {
		fmt.Println("errors.As code:", target.Code)
	}

	// 4) 接口值比较：动态类型相同且动态值相等才为 true
	var a any = 42
	var b any = 42
	fmt.Println("a == b:", a == b) // true：动态类型都是 int，值相等

	// 5) 不可比较类型做接口比较会 panic（取消注释可复现）
	// var s1 any = []int{1, 2}
	// var s2 any = []int{1, 2}
	// fmt.Println(s1 == s2) // panic: comparing uncomparable type []int
}
